const bgm = new Audio(AUDIO.music);
bgm.loop = true;
bgm.volume = 0.52;
let soundOn = true;
function startMusic() {
  if(!soundOn) return;
  bgm.play().catch(()=>{});
}
function playSfx(src, volume=0.65) {
  if(!soundOn) return;
  const a = new Audio(src);
  a.volume = volume;
  a.play().catch(()=>{});
}
function toggleSound() {
  soundOn = !soundOn;
  if(soundOn) startMusic();
  else bgm.pause();
}

function playAngelNote(){
  if(!soundOn) return;
  const AC=window.AudioContext || window.webkitAudioContext;
  if(!AC) return;
  if(!singAudioCtx) singAudioCtx=new AC();
  if(singAudioCtx.state==="suspended") singAudioCtx.resume().catch(()=>{});
  const notes=[440,523.25,659.25,523.25];
  const now=singAudioCtx.currentTime;
  const o=singAudioCtx.createOscillator();
  const g=singAudioCtx.createGain();
  o.type="sine";
  o.frequency.setValueAtTime(notes[singNoteStep++%notes.length],now);
  g.gain.setValueAtTime(.0001,now);
  g.gain.exponentialRampToValueAtTime(.035,now+.018);
  g.gain.exponentialRampToValueAtTime(.0001,now+.14);
  o.connect(g).connect(singAudioCtx.destination);
  o.start(now);
  o.stop(now+.15);
}
;

