function freshSave() {
  return {
    bits:"0".repeat(999),
    scoreSkulls:null,
    boxes:"",
    key:false,
    chapel:false,
    health:3,
    heartTaken:false,
    x:170,
    secret:""
  };
}
const trailerScene = new URLSearchParams(location.search).get("trailer") || "";
let save;
if(trailerScene){
  save=freshSave();
  if(trailerScene==="key"){
    save.scoreSkulls=999;
    save.bits="1".repeat(999);
    save.x=MOUND_X-110;
  } else if(trailerScene==="goat"){
    save.scoreSkulls=999;
    save.bits="1".repeat(999);
    save.key=true;
    save.x=GOAT_X-145;
  } else if(trailerScene==="tea"){
    save.scoreSkulls=321;
    save.x=570;
  } else if(trailerScene==="hand"){
    save.scoreSkulls=143;
    save.x=3200;
  } else if(trailerScene==="house"){
    save.scoreSkulls=999;
    save.bits="1".repeat(999);
    save.key=true;
    save.x=CHAPEL_X-300;
  }
} else {
  try { save=Object.assign(freshSave(), JSON.parse(localStorage.getItem(SAVE_KEY)||"{}")); }
  catch(e) { save=freshSave(); }
}
if (!save.bits || save.bits.length !== 999) save.bits = "0".repeat(999);
let collected = save.bits.split("").map(c => c === "1");
const rawCollectedCount = collected.reduce((a,b)=>a+(b?1:0),0);
let skullCount = Number.isFinite(save.scoreSkulls) ? clamp(save.scoreSkulls,0,999) : rawCollectedCount;
let health = Number.isFinite(save.health) ? clamp(save.health,0,3) : 3;
if(typeof save.heartTaken !== "boolean") save.heartTaken=false;

let lastPersistAt=0;
function persist(force=false) {
  const now=performance.now();
  if (!force && now-lastPersistAt < 5000) return;
  lastPersistAt=now;
  save.bits = collected.map(v=>v?"1":"0").join("");
  save.scoreSkulls = skullCount;
  save.boxes = skullBoxes.map(b=>b.opened?"1":"0").join("");
  save.health = health;
  save.heartTaken = !!save.heartTaken;
  save.x = Math.round(player.x);
  localStorage.setItem(SAVE_KEY, JSON.stringify(save));
}

function hash(n) {
  n = Math.sin(n * 12.9898 + 78.233) * 43758.5453;
  return n - Math.floor(n);
}
function clamp(v,a,b) { return Math.max(a,Math.min(b,v)); }
function terrainHill(x,c,r,h){
  const d=Math.abs(x-c);
  if(d>=r) return 0;
  const n=1-(d/r);
  return Math.round(Math.sin(n*Math.PI*0.5)*h);
}
function groundY(x) {
  const natural = Math.sin(x * 0.0021) * 4 + Math.sin(x * 0.0063) * 2;

  // A few shallow, hand-placed mounds so the world feels less flat.
  // Hills lift the ground upward, so they subtract from the base y.
  const hills =
    terrainHill(x, 760, 210, 12) +
    terrainHill(x, 1550, 270, 18) +
    terrainHill(x, 2480, 220, 10) +
    terrainHill(x, 3370, 320, 22) +
    terrainHill(x, 4290, 240, 14) +
    terrainHill(x, 5110, 190, 9);

  return GROUND_BASE + Math.round(natural) - hills;
}

const skulls = [];
(function buildSkulls() {
  for(let i=0;i<999;i++) {
    const t=(i+0.5)/999;
    let x=420 + t*(CHAPEL_X-820);
    x += (hash(i*7.31)-0.5)*84;
    if (Math.abs(x - GOAT_X) < 120) x += 120;

    let y = groundY(x) - 8;
    const r = hash(i*19.13);

    // Keep plenty near the ground, but now scatter some much higher
    // so the sky reads more dramatic and tea/flight becomes rewarding.
    if(r > 0.985) {
      y -= 88 + Math.floor(hash(i*2.3) * 28);      // very high sky skulls
    } else if(r > 0.945) {
      y -= 58 + Math.floor(hash(i*3.9) * 24);      // high sky skulls
    } else if(r > 0.68) {
      y -= 24 + Math.floor(hash(i*4.7) * 18);      // normal jump skulls
    } else if(r > 0.48) {
      y -= 10 + Math.floor(hash(i*5.1) * 8);       // small hop skulls
    }

    skulls.push({x,y,i});
  }
})();

const SKULL_BUCKET_SIZE=256;
const skullBuckets=[];
for(const s of skulls){
  const bi=Math.floor(s.x/SKULL_BUCKET_SIZE);
  (skullBuckets[bi] ||= []).push(s);
}
function forNearbySkulls(x0,x1,fn){
  const b0=Math.max(0,Math.floor(x0/SKULL_BUCKET_SIZE));
  const b1=Math.min(skullBuckets.length-1,Math.floor(x1/SKULL_BUCKET_SIZE));
  for(let bi=b0;bi<=b1;bi++){
    const bucket=skullBuckets[bi];
    if(!bucket) continue;
    for(const s of bucket) fn(s);
  }
}

const teas = [];
for(let x=760, i=0; x<CHAPEL_X-620; x+=1380, i++) {
  teas.push({x:x+(i%2?110:-40), y:groundY(x)-12, used:false, respawn:0});
}

// Skull boxes: each one is worth +20 skulls.
const skullBoxes = [];
for(let x=980, i=0; x<CHAPEL_X-520; x+=820, i++) {
  skullBoxes.push({
    x:x + (i%3===0 ? 80 : i%3===1 ? -55 : 20),
    y:groundY(x)-18,
    opened:false,
    i
  });
}
if(save.boxes && save.boxes.length===skullBoxes.length) {
  skullBoxes.forEach((b,i)=>b.opened = save.boxes[i]==="1");
}

