const keys={};

const startScreen = document.getElementById("start");
const btnContinue = document.getElementById("btnContinue");
const btnNewGame = document.getElementById("btnNewGame");

function beginGame() {
  started = true;
  startScreen.style.display = "none";
  startMusic();
}

function beginNewGame() {
  localStorage.removeItem(SAVE_KEY);
  location.reload();
}

if(btnContinue) btnContinue.addEventListener("click", beginGame);
if(btnNewGame) btnNewGame.addEventListener("click", beginNewGame);

addEventListener("keydown",e=>{
  const target=e.target;
  const typing=target && (target.tagName==="INPUT" || target.tagName==="TEXTAREA" || target.isContentEditable);
  if(typing) return;
  keys[e.code]=true;
  if(["ArrowLeft","ArrowRight","ArrowUp","ArrowDown","Space","KeyF"].includes(e.code)) e.preventDefault();
  if(!started && e.code==="Enter") {
    beginGame();
  }
  if(!started && e.code==="KeyN") {
    beginNewGame();
  }
  if(started && e.code==="Escape" && document.getElementById("vault").style.display==="none") paused=!paused;
  if(started && e.code==="KeyM") toggleSound();
  if(started && e.code==="KeyR" && gameOver && !gameCompleted) beginNewGame();
  if(started && e.code==="Enter" && gameOver && gameCompleted && completionSubmitted) window.location.href=POSTHUMAN_URL;
  if(started && e.code==="KeyE") interact();
});
addEventListener("keyup",e=>{
  keys[e.code]=false;
});

const nameForm=document.getElementById("nameForm");
const albumButton=document.getElementById("albumButton");

if(nameForm){
  nameForm.addEventListener("submit",async(e)=>{
    e.preventDefault();
    if(completionSubmitted) return;

    const input=document.getElementById("playerName");
    const status=document.getElementById("leaderStatus");
    const submit=document.getElementById("submitScore");
    const name=(input.value||"").trim().replace(/\s+/g," ").slice(0,24);

    if(name.length<1){
      status.textContent="ENTER A NAME.";
      input.focus();
      return;
    }

    submit.disabled=true;
    submit.textContent="ADDING...";
    status.textContent="SAVING TO LIVE LEADERBOARD...";

    try{
      const res=await fetch("/api/leaderboard",{
        method:"POST",
        headers:{"content-type":"application/json"},
        body:JSON.stringify({name,score:completionScore})
      });
      if(!res.ok) throw new Error("save failed");

      const data=await res.json();
      completionSubmitted=true;
      completionEntryId=data.id||"";
      input.disabled=true;
      submit.style.display="none";
      status.textContent="YOU'RE ON THE BOARD.";
      renderLiveLeaderboard(data.entries||[],completionEntryId);
      beginAlbumCountdown(10);
    }catch(err){
      submit.disabled=false;
      submit.textContent="TRY AGAIN";
      status.textContent="COULDN'T SAVE. TAP TRY AGAIN.";
    }
  });
}

