function say(s,t=2.8) {
  msg=s; msgTimer=t;
}

function getFinalGameScore(){
  const openedBoxes=skullBoxes.reduce((n,b)=>n+(b.opened?1:0),0);
  return skullCount*20 + openedBoxes*250 + (save.key?1000:0);
}

function renderLiveLeaderboard(entries, myId=""){
  const list=document.getElementById("leaderboard");
  const wrap=document.getElementById("leaderboardWrap");
  list.innerHTML="";

  if(!Array.isArray(entries) || entries.length===0){
    const li=document.createElement("li");
    li.textContent="NO ENTRIES YET.";
    list.appendChild(li);
    wrap.style.display="block";
    return;
  }

  entries.slice(0,15).forEach((entry,index)=>{
    const li=document.createElement("li");
    if(entry.id===myId) li.classList.add("me");

    const rank=document.createElement("span");
    rank.className="rank";
    rank.textContent=String(index+1).padStart(2,"0");

    const name=document.createElement("span");
    name.textContent=String(entry.name||"UNKNOWN").toUpperCase();

    const score=document.createElement("span");
    score.className="score";
    score.textContent=String(entry.score||0).padStart(6,"0");

    li.append(rank,name,score);
    list.appendChild(li);
  });

  wrap.style.display="block";
}

async function loadLeaderboard(){
  const status=document.getElementById("leaderStatus");
  try{
    const res=await fetch("/api/leaderboard",{cache:"no-store"});
    if(!res.ok) throw new Error("leaderboard unavailable");
    const data=await res.json();
    renderLiveLeaderboard(data.entries||[],completionEntryId);
    return data.entries||[];
  }catch(err){
    status.textContent="LIVE LEADERBOARD COULD NOT LOAD.";
    return [];
  }
}

function beginAlbumCountdown(seconds=10){
  const countdown=document.getElementById("redirectCountdown");
  const albumButton=document.getElementById("albumButton");
  albumButton.style.display="block";
  countdown.style.display="block";

  let left=seconds;
  countdown.textContent="OPENING POSTHUMAN IN "+left+"...";
  const timer=setInterval(()=>{
    left--;
    if(left<=0){
      clearInterval(timer);
      window.location.href=POSTHUMAN_URL;
      return;
    }
    countdown.textContent="OPENING POSTHUMAN IN "+left+"...";
  },1000);
}

async function showCompletionOverlay(){
  completionScore=getFinalGameScore();
  const overlay=document.getElementById("completionOverlay");
  const status=document.getElementById("leaderStatus");
  overlay.classList.add("show");
  status.textContent="";

  // Show the current board immediately, then require a name before album redirect.
  await loadLeaderboard();

  setTimeout(()=>{
    const input=document.getElementById("playerName");
    if(input) input.focus({preventScroll:true});
  },100);
}

function spawnHeadlessSkeletons() {
  devils = [];
  for(let i=0;i<7;i++){
    let x = GOAT_X + 240 + i*225 + ((i%2)?50:-28);
    if(x > CHAPEL_X - 170) break;
    devils.push({
      x:x,
      y:groundY(x)-18,
      vx:0,
      active:true,
      rise:0,
      phase:"emerge",
      hitTimer:0
    });
  }
}

function interact() {
  if (paused) return;

  // Tea gets first priority. Keep this intentionally simple on touch controls.
  let nearbyTea=null, nearbyTeaDist=999;
  for (const t of teas) {
    if (t.used) continue;
    const dx=Math.abs(player.x-t.x);
    const dy=Math.abs((player.y+player.h)-(t.y+12));
    if(dx<nearbyTeaDist && dx<54 && dy<78){
      nearbyTea=t;
      nearbyTeaDist=dx;
    }
  }

  if(nearbyTea){
    nearbyTea.used=true;
    nearbyTea.respawn=26;
    player.interactAnim=0;
    player.bendAnim=.10;
    player.flight=10.0;
    player.grounded=false;
    player.vy=-72;
    say("OPIUM TEA, MAKE ME AN ANGEL!",2.8);
    return;
  }

  player.interactAnim = 0;
  player.bendAnim = Math.max(player.bendAnim, 0.42);

  // Sacred burning heart restores all 3 lives.
  if(!save.heartTaken && Math.abs(player.x-SACRED_HEART_X)<42){
    if(health<3){
      health=3;
      save.heartTaken=true;
      flash=.42;
      persist(true);
      say("THE SACRED HEART RESTORES YOUR LIFE.",2.8);
      return;
    } else {
      say("THE SACRED HEART STILL BURNS.",1.8);
      return;
    }
  }

  // Shout into the old well.
  if(Math.abs(player.x-WELL_X)<44){
    const wellShouts = [
      "NOPE, NO SKULLS DOWN THERE!",
      "HELLOOOOOOOO!"
    ];
    flash=.18;
    say(wellShouts[Math.floor(hash(frame*.619 + player.x*.017)*wellShouts.length)],2.0);
    return;
  }

  // Skull box pickup: +20 skulls, capped at 999.
  let bestBox=null, boxDist=999;
  for(const b of skullBoxes) {
    if(b.opened) continue;
    const d=Math.abs(player.x-b.x);
    if(d<boxDist) { boxDist=d; bestBox=b; }
  }
  if(bestBox && boxDist<34 && Math.abs((bestBox.y+12)-(player.y+18))<42) {
    bestBox.opened=true;
    const before=skullCount;
    skullCount=clamp(skullCount+20,0,999);
    const gained=skullCount-before;
    flash=0.28;
    playSfx(AUDIO.box,0.72);
    say("SKULL BOX +" + gained + " SKULLS", 2.1);
    if(skullCount===999 && !save.key) {
      keyVisible=true;
      if(!skull999Announced){
        skull999Announced=true;
        say("999 SKULLS! BACK TO THE MOUND.", 4.2);
      }
    }
    persist(true);
    return;
  }

  if (!player.mounted && Math.abs(player.x - GOAT_X) < 62) {
    if(save.key) {
      player.mounted=true;
      player.flight=0;
      player.y=groundY(player.x)-player.h;
      if(!devils.length) spawnHeadlessSkeletons();
      say("THE GOAT BOWS. RIDE TOWARD THE HOUSE OF LOST YOUTH.",3.3);
    } else {
      const lines = [
        "THE GOAT WATCHES THE MOUND.",
        "EVERY SKULL RETURNS TO THE SAME HILL.",
        "BRING THE KEY. THEN I WILL CARRY YOU."
      ];
      say(lines[Math.floor(hash(frame*0.73) * lines.length)],3.2);
    }
    return;
  }

  if (keyVisible && Math.abs(player.x - (MOUND_X + 36)) < 38) {
    player.interactAnim=0;
    player.bendAnim=0;
    player.keyReachAnim=.85;
    save.key=true; keyVisible=false; flash=0.45; persist(true);
    say("THE SKELETON KEY IS YOURS.",3.0);
    return;
  }

  if (Math.abs(player.x - CHAPEL_X) < 76) {
    if (!save.key) {
      say("THE HOUSE OF LOST YOUTH IS LOCKED.", 2.8);
    } else if(!ending && !gameOver) {
      save.chapel=true;
      persist(true);
      ending=true;
      endingTime=0;
      player.vx=0;
      playSfx(AUDIO.fire,.72);
      bgm.volume=.28;
    }
  }
}

// content vault
const vault=document.getElementById("vault");
const audio=document.getElementById("audio");
const video=document.getElementById("video");
const tracklist=document.getElementById("tracklist");
let tracks=[], trackIndex=0;
function openVault() { vault.style.display="flex"; paused=true; }
function closeVault() { vault.style.display="none"; paused=false; }
document.getElementById("closeVault").onclick=closeVault;
document.getElementById("audioFiles").onchange=e=> {
  tracks=[...e.target.files].map(f=>({name:f.name,url:URL.createObjectURL(f)}));
  tracklist.innerHTML="";
  tracks.forEach((t,i)=>{
    const li=document.createElement("li");
    li.textContent=(i+1)+". "+t.name;
    li.onclick=()=>playTrack(i);
    tracklist.appendChild(li);
  });
  if (tracks.length) playTrack(0);
};
function playTrack(i) {
  trackIndex=i;
  video.style.display="none";
  audio.style.display="block";
  audio.src=tracks[i].url;
  audio.play().catch(()=>{});
  [...tracklist.children].forEach((li,n)=>li.classList.toggle("active",n===i));
}
audio.onended=()=>{ if(tracks.length) playTrack((trackIndex+1)%tracks.length); };
document.getElementById("videoFile").onchange=e=> {
  const f=e.target.files[0]; if(!f) return;
  audio.pause(); video.src=URL.createObjectURL(f); video.style.display="block"; video.play().catch(()=>{});
};
document.getElementById("secretBtn").onclick=()=> {
  const s=prompt("SECRET TEXT / CODE", save.secret || "");
  if (s !== null) {
    save.secret=s;
    persist(true);
    document.getElementById("secretBox").textContent=s || "NO SECRET LOADED.";
  }
};
document.getElementById("secretBox").textContent=save.secret || "NO SECRET LOADED.";

function rect(x,y,w,h,c) {
  ctx.fillStyle=c; ctx.fillRect(Math.round(x),Math.round(y),Math.round(w),Math.round(h));
}
